// ---- FlappyHoop cloud save (Google Play Games Saved Games) ----
private com.google.android.gms.games.snapshot.Snapshot FlappyCloudSnapshot = null;

public void AndroidThunkJava_FlappyCloudOpen(final String Name, final long RequestId)
{
	FlappyCloudOpen(Name, RequestId, 0);
}

private void FlappyCloudOpen(final String Name, final long RequestId, final int Attempt)
{
	final com.google.android.gms.games.SnapshotsClient Client = com.google.android.gms.games.PlayGames.getSnapshotsClient(this);
	Client.open(Name, true, com.google.android.gms.games.SnapshotsClient.RESOLUTION_POLICY_MOST_RECENTLY_MODIFIED)
		.addOnCompleteListener(Task ->
		{
			if (!Task.isSuccessful())
			{
				Log.debug("[FlappyCloud] open failed: " + Task.getException());
				nativeFlappyCloudLoaded(RequestId, false, null);
				return;
			}

			com.google.android.gms.games.SnapshotsClient.DataOrConflict<com.google.android.gms.games.snapshot.Snapshot> Result = Task.getResult();
			if (Result.isConflict())
			{
				// The policy normally resolves conflicts itself; if one still comes back, keep the newest and reopen.
				com.google.android.gms.games.SnapshotsClient.SnapshotConflict Conflict = Result.getConflict();
				if (Conflict == null || Attempt >= 3)
				{
					nativeFlappyCloudLoaded(RequestId, false, null);
					return;
				}
				Client.resolveConflict(Conflict.getConflictId(), Conflict.getSnapshot())
					.addOnCompleteListener(ResolveTask -> FlappyCloudOpen(Name, RequestId, Attempt + 1));
				return;
			}

			com.google.android.gms.games.snapshot.Snapshot Snapshot = Result.getData();
			byte[] Data = null;
			try
			{
				Data = Snapshot.getSnapshotContents().readFully();
			}
			catch (java.io.IOException e)
			{
				Log.debug("[FlappyCloud] read failed: " + e);
				Client.discardAndClose(Snapshot);
				nativeFlappyCloudLoaded(RequestId, false, null);
				return;
			}

			if (FlappyCloudSnapshot != null)
			{
				Client.discardAndClose(FlappyCloudSnapshot);
			}
			FlappyCloudSnapshot = Snapshot;
			nativeFlappyCloudLoaded(RequestId, true, Data);
		});
}

public void AndroidThunkJava_FlappyCloudCommit(final byte[] Data, final long RequestId)
{
	final com.google.android.gms.games.snapshot.Snapshot Snapshot = FlappyCloudSnapshot;
	FlappyCloudSnapshot = null;
	if (Snapshot == null)
	{
		nativeFlappyCloudCommitted(RequestId, false);
		return;
	}

	com.google.android.gms.games.SnapshotsClient Client = com.google.android.gms.games.PlayGames.getSnapshotsClient(this);
	Snapshot.getSnapshotContents().writeBytes(Data);
	com.google.android.gms.games.snapshot.SnapshotMetadataChange Change =
		new com.google.android.gms.games.snapshot.SnapshotMetadataChange.Builder()
			.setDescription("Flappy Hoop progress")
			.build();
	Client.commitAndClose(Snapshot, Change)
		.addOnCompleteListener(Task ->
		{
			if (!Task.isSuccessful())
			{
				Log.debug("[FlappyCloud] commit failed: " + Task.getException());
			}
			nativeFlappyCloudCommitted(RequestId, Task.isSuccessful());
		});
}

public void AndroidThunkJava_FlappyCloudDiscard()
{
	if (FlappyCloudSnapshot != null)
	{
		com.google.android.gms.games.PlayGames.getSnapshotsClient(this).discardAndClose(FlappyCloudSnapshot);
		FlappyCloudSnapshot = null;
	}
}

