public void AndroidThunkJava_FlappyCloudOpen(final String Name, final long RequestId)
{
	nativeFlappyCloudLoaded(RequestId, false, null);
}

public void AndroidThunkJava_FlappyCloudCommit(final byte[] Data, final long RequestId)
{
