// ---- FlappyHoop native message popup (FlappyNativeDialog::Show) ----
public void AndroidThunkJava_FlappyShowMessage(final String Title, final String Message, final String ButtonText)
{
	runOnUiThread(() ->
	{
		if (isFinishing())
		{
			return;
		}
		try
		{
			new android.app.AlertDialog.Builder(this)
				.setTitle(Title)
				.setMessage(Message)
				.setPositiveButton(ButtonText, null)
				.show();
		}
		catch (Exception e)
		{
			Log.debug("[FlappyDialog] could not show the message: " + e);
		}
	});
}

public native void nativeFlappyCloudLoaded(long RequestId, boolean bSuccess, byte[] Data);
public native void nativeFlappyCloudCommitted(long RequestId, boolean bSuccess);
